def count_valid_joke_sets(N, jokes, supervisors):
    # Build the tree structure
    tree = defaultdict(list)
    for subordinate, superior in supervisors:
        tree[superior].append(subordinate)

    # Dynamic programming table
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # DFS to calculate the number of valid joke sets
    def dfs(node):
        # Base case: leaf node
        if node not in tree:
            dp[node][jokes[node - 1]] = 1
            return

        # Recursive case
        for child in tree[node]:
            dfs(child)

        # Calculate dp values for current node
        for j in range(1, N + 1):
            if j == jokes[node - 1]:
                continue
            dp[node][j] = 1
            for child in tree[node]:
                child_sum = sum(dp[child])
                dp[node][j] *= child_sum

        # Ensure the joke set is consecutive
        for j in range(1, N + 1):
